#!/usr/bin/env python3
# patch-158-G2: reschedule modal, cancel button, resource picker in multi-asset view
"""
Three pieces of missing functionality after first round of testing:

1. Reschedule button + modal. The legacy view has a complex week-strip
   time picker (~330 lines markup + JS). Extracted into a new shared
   partial: resources/views/tenant/appointments/_reschedule_modal.blade.php.
   Multi-asset view includes it.
   Legacy view continues to use its inline copy for now (untouched).
   Future cleanup: have legacy include the partial too.

2. Cancel appointment button. New "Cancel appointment" button in the
   rail (red danger, hidden when terminal). Uses IntakeConfirm,
   posts op=status status=cancelled, redirects to calendar on success.

3. Resource picker. New Resource card in the rail showing currently-
   assigned resource and a Change-to select. Uses the same data-attr
   API as legacy (data-appt-resource-card / data-appt-resource-select
   / data-appt-resource-save) so the existing public/js/tenant/
   appointment-resource.js script auto-binds the save handler. The
   script is now loaded by both views.

No controller changes. Reuses existing ops:
  - status (cancel)
  - change_resource (via shared JS)
  - reschedule (via existing tenant.appointments.week-times endpoint)

Standalone Python. Idempotent.
"""
